<?php
namespace App\Services\Hr;use App\Models\Staff;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\ValidationException;
class HrNotificationService{
public function queue(string$companyId,string$eventType,string$sourceType,string$sourceId,string$staffId,array$variables):array{$staff=Staff::query()->whereKey($staffId)->where('company_id',$companyId)->whereNull('employment_ended_at')->first();if(!$staff||!$staff->user_id)return[];$user=DB::table('users')->where('id',$staff->user_id)->where('is_active',true)->first();if(!$user)return[];$rows=[];foreach(['in_app','email','sms']as$channel){$template=DB::table('hr_notification_template_versions')->where('company_id',$companyId)->where('event_type',$eventType)->where('channel',$channel)->where('status','approved')->whereDate('effective_from','<=',now())->where(fn($q)=>$q->whereNull('effective_until')->orWhereDate('effective_until','>=',now()))->latest('version')->first();if(!$template)continue;$destination=$channel==='email'?($user->email??null):($channel==='sms'?($user->phone??null):(string)$user->id);if(!$destination)continue;$preference=DB::table('hr_notification_preferences')->where('staff_id',$staffId)->where('event_type',$eventType)->where('channel',$channel)->value('enabled');if(!$template->mandatory&&$preference===false)continue;$allowed=json_decode($template->allowed_placeholders,true)?:[];if(array_diff(array_keys($variables),$allowed))throw ValidationException::withMessages(['variables'=>'Notification variables exceed the approved template contract.']);preg_match_all('/\{\{\s*([a-zA-Z0-9_.-]+)\s*\}\}/',(string)$template->subject_template.' '.(string)$template->body_template,$matches);if(array_diff(array_unique($matches[1]),array_keys($variables)))throw ValidationException::withMessages(['variables'=>'Notification variables do not satisfy every required template placeholder.']);$render=fn($text)=>preg_replace_callback('/\{\{\s*([a-zA-Z0-9_.-]+)\s*\}\}/',fn($m)=>(string)$variables[$m[1]],(string)$text);$payload=['destination'=>$destination,'subject'=>$render($template->subject_template),'body'=>$render($template->body_template),'source_type'=>$sourceType,'source_id'=>$sourceId];$checksum=hash('sha256',json_encode($payload,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));$key='hr-notification:'.$template->id.':'.$sourceType.':'.$sourceId.':'.$staffId;$existing=DB::table('hr_notification_outbox')->where('idempotency_key',$key)->first();if($existing){$rows[]=$existing;continue;}$id=(string)Str::uuid();DB::table('hr_notification_outbox')->insert(['id'=>$id,'company_id'=>$companyId,'template_version_id'=>$template->id,'recipient_staff_id'=>$staffId,'recipient_user_id'=>$staff->user_id,'event_type'=>$eventType,'channel'=>$channel,'source_type'=>$sourceType,'source_id'=>$sourceId,'encrypted_rendered_payload'=>encrypt($payload),'payload_checksum'=>$checksum,'idempotency_key'=>$key,'status'=>'queued','available_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);$rows[]=DB::table('hr_notification_outbox')->find($id);}return$rows;}}
